def kmp_table(pattern):
    """Computes the longest proper prefix suffix (LPS) table for the KMP algorithm."""
    length = 0  # Length of the previous longest prefix suffix
    i = 1
    table = [0] * len(pattern)
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            table[i] = length
            i += 1
        else:
            if length != 0:
                length = table[length - 1]
            else:
                table[i] = 0
                i += 1
    return table

def kmp_search(text, pattern):
    """Performs KMP search to find occurrences of the pattern in the text."""
    table = kmp_table(pattern)
    i = 0  # Index for text
    j = 0  # Index for pattern
    occurrences = []
    while i < len(text):
        if pattern[j] == text[i]:
            i += 1
            j += 1

        if j == len(pattern):
            occurrences.append(i - j)
            j = table[j - 1]

        elif i < len(text) and pattern[j] != text[i]:
            if j != 0:
                j = table[j - 1]
            else:
                i += 1
    return occurrences
```

The KMP algorithm efficiently finds occurrences of a pattern within a text by precomputing a table that guides the search, avoiding unnecessary comparisons.  This table leverages the pattern's internal structure to intelligently skip sections of the text when a mismatch occurs.

