def find_super_primes(n):
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, int(n**0.5) + 1):
        if is_prime[p]:
            for i in range(p*p, n + 1, p):
                is_prime[i] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
    super_primes = []
    for i in range(1, len(primes)):
        if primes[i] <= n and primes[i-1] == primes[i]:
            super_primes.append(primes[i])
    return super_primes
```

